-- kompile-showcase.lua: standalone build. Generated by tools/bundle.py. Don't edit by hand.

--[[
	Kompile UI showcase: every element in one window. It doesn't touch the game.
	No-setup version (library included): dist/kompile-showcase.lua
]]

local Library = (function()
--[[
	Kompile UI v4
	A solid, compact Roblox UI library for the Kompile hub: sidebar tabs, bordered
	groupboxes with their titles set into the border, checkboxes, feature search and
	a status bar.

	local Window = Library:CreateWindow({ Title = "Kompile", Footer = "v1.0.0", ToggleKey = "RightShift" })
	local Tab = Window:AddTab("Main")
	local Box = Tab:AddLeftGroupbox("Movement")
	Box:AddToggle("MyToggle", { Text = "Enabled", Default = false, Callback = function(on) end })
]]

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local GuiService = game:GetService("GuiService")
local CoreGui = game:GetService("CoreGui")

local LocalPlayer = Players.LocalPlayer

local Library = {
	Version = "4.8.0",
	Options = {},
	Unloaded = false,
	Picking = false,
	Folder = "Kompile",
	UserScale = 1,
	GlowEnabled = true,
	KeybindListEnabled = true,
	Theme = {
		Background = Color3.fromHex("050408"), -- content area and groupboxes
		Chrome = Color3.fromHex("08070c"), -- title bar, sidebar, status bar
		Field = Color3.fromHex("0f0d14"), -- inputs, checkboxes, tracks
		Button = Color3.fromHex("141219"),
		Hover = Color3.fromHex("110f17"),
		Border = Color3.fromHex("1a1723"),
		BorderLight = Color3.fromHex("26222f"),
		Text = Color3.fromHex("e9e6f5"),
		SubText = Color3.fromHex("938da3"),
		Muted = Color3.fromHex("5d586b"),
		Accent = Color3.fromHex("9b5cff"),
	},
	AccentPresets = {
		Violet = Color3.fromHex("9b5cff"),
		Aqua = Color3.fromHex("3ee6d0"),
		Pink = Color3.fromHex("ff6fb5"),
		Mint = Color3.fromHex("5ce68a"),
		Amber = Color3.fromHex("ffb547"),
		Crimson = Color3.fromHex("ff4d6a"),
	},
}

local Registry = {} -- { instance, { property = themeKey } }
local ThemeCallbacks = {}
local Connections = {}
local UnloadCallbacks = {}
local SearchIndex = {}

local FAMILY = "rbxasset://fonts/families/BuilderSans.json"
local FONT = Font.new(FAMILY, Enum.FontWeight.Regular)
local FONT_MEDIUM = Font.new(FAMILY, Enum.FontWeight.Medium)
local FONT_SEMI = Font.new(FAMILY, Enum.FontWeight.SemiBold)
local FONT_BOLD = Font.new(FAMILY, Enum.FontWeight.Bold)

local RADIUS = 6 -- controls, boxes, tabs
local WINDOW_RADIUS = 10
local SIDEBAR = 180
local STRIP = 2 -- accent strip across the top
local HEADER = 50 -- page title row, and the logo block in the sidebar
local STATUSBAR = 26

local TWEEN = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local TWEEN_FAST = TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

local KEY_ALIASES = { MB1 = "MouseButton1", MB2 = "MouseButton2", MB3 = "MouseButton3" }
local KEY_SHORT = { MouseButton1 = "MB1", MouseButton2 = "MB2", MouseButton3 = "MB3" }

--// Helpers

local function create(className, props, children)
	local instance = Instance.new(className)
	if instance:IsA("GuiObject") then
		instance.BorderSizePixel = 0
	end
	local parent
	for key, value in pairs(props or {}) do
		if key == "Theme" then
			table.insert(Registry, { instance, value })
			for property, themeKey in pairs(value) do
				instance[property] = Library.Theme[themeKey]
			end
		elseif key == "Parent" then
			parent = value
		else
			instance[key] = value
		end
	end
	for _, child in ipairs(children or {}) do
		child.Parent = instance
	end
	instance.Parent = parent
	return instance
end

local function text(props)
	if props.BackgroundTransparency == nil then
		props.BackgroundTransparency = 1
	end
	props.FontFace = props.FontFace or FONT
	props.TextSize = props.TextSize or 13
	props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
	if props.Theme == nil then
		props.Theme = { TextColor3 = "Text" }
	elseif props.Theme == false then
		props.Theme = nil
	end
	return create("TextLabel", props)
end

local function corner(radius)
	return create("UICorner", { CornerRadius = UDim.new(0, radius or RADIUS) })
end

local function stroke(themeKey)
	return create("UIStroke", {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Theme = { Color = themeKey or "Border" },
	})
end

local function padding(top, right, bottom, left)
	return create("UIPadding", {
		PaddingTop = UDim.new(0, top),
		PaddingRight = UDim.new(0, right or top),
		PaddingBottom = UDim.new(0, bottom or top),
		PaddingLeft = UDim.new(0, left or right or top),
	})
end

local function list(gap, horizontal, props)
	local layout = create("UIListLayout", {
		Padding = UDim.new(0, gap or 0),
		FillDirection = horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
	})
	for key, value in pairs(props or {}) do
		layout[key] = value
	end
	return layout
end

local function tween(instance, goals, info)
	local t = TweenService:Create(instance, info or TWEEN, goals)
	t:Play()
	return t
end

local function connect(signal, fn)
	local connection = signal:Connect(fn)
	table.insert(Connections, connection)
	return connection
end

local function fire(fn, ...)
	if type(fn) ~= "function" then
		return
	end
	local args = table.pack(...)
	task.spawn(function()
		local ok, err = pcall(fn, table.unpack(args, 1, args.n))
		if not ok then
			warn("[Kompile UI] Callback error: " .. tostring(err))
		end
	end)
end

local function scaleFactor()
	local s = Library.Scale and Library.Scale.Scale or 1
	return s > 0 and s or 1
end

local function isPointer(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function isMove(input)
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

local function parseKey(value)
	if typeof(value) == "EnumItem" then
		return value
	end
	if type(value) ~= "string" or value == "" or value == "None" then
		return nil
	end
	value = KEY_ALIASES[value] or value
	local ok, key = pcall(function()
		return Enum.KeyCode[value]
	end)
	if ok and key then
		return key
	end
	ok, key = pcall(function()
		return Enum.UserInputType[value]
	end)
	if ok and key then
		return key
	end
	return nil
end

local function keyName(key)
	if not key then
		return "None"
	end
	return KEY_SHORT[key.Name] or key.Name
end

local function inputMatches(input, key)
	if not key then
		return false
	end
	if key.EnumType == Enum.KeyCode then
		return input.KeyCode == key
	end
	return input.UserInputType == key
end

local function parentGui(gui)
	local ok, hui = pcall(function()
		return gethui()
	end)
	if ok and typeof(hui) == "Instance" then
		gui.Parent = hui
		return
	end
	if pcall(function()
		gui.Parent = CoreGui
	end) then
		return
	end
	gui.Parent = LocalPlayer:WaitForChild("PlayerGui")
end

local function attachTooltip(target, tip)
	if not tip then
		return
	end
	target.MouseEnter:Connect(function()
		local Tooltip = Library.Tooltip
		if Tooltip then
			local mouse = UserInputService:GetMouseLocation() - GuiService:GetGuiInset()
			Tooltip.Text = tip
			Tooltip.Position = UDim2.fromOffset(mouse.X + 14, mouse.Y + 16)
			Tooltip.Visible = true
		end
	end)
	target.MouseLeave:Connect(function()
		if Library.Tooltip then
			Library.Tooltip.Visible = false
		end
	end)
end

-- Brief lime outline around an element, used when search jumps to it.
local function flash(target)
	local Outline = create("UIStroke", {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Theme = { Color = "Accent" },
		Parent = target,
	})
	task.delay(0.9, function()
		tween(Outline, { Transparency = 1 }, TweenInfo.new(0.5)).Completed:Connect(function()
			Outline:Destroy()
		end)
	end)
end

--// Theme

function Library:SetTheme(changes)
	for key, value in pairs(changes) do
		self.Theme[key] = value
	end
	for _, entry in ipairs(Registry) do
		for property, themeKey in pairs(entry[2]) do
			entry[1][property] = self.Theme[themeKey]
		end
	end
	for _, paint in ipairs(ThemeCallbacks) do
		paint()
	end
end

function Library:SetScale(scale)
	self.UserScale = scale
	if self.Scale then
		self.Scale.Scale = scale
	end
	if self.PanelScale then
		self.PanelScale.Scale = scale
	end
end

--// Options

local function newOption(id, kind, opts)
	local option = {
		Id = id,
		Type = kind,
		Callback = opts.Callback,
		Save = opts.Save ~= false,
		Changed = {},
	}
	function option:OnChanged(fn)
		table.insert(self.Changed, fn)
	end
	function option:_emit()
		fire(self.Callback, self.Value)
		for _, fn in ipairs(self.Changed) do
			fire(fn, self.Value)
		end
	end
	if id then
		if Library.Options[id] then
			warn("[Kompile UI] Duplicate option id: " .. tostring(id))
		end
		Library.Options[id] = option
	end
	return option
end

-- Every keybind, for the active keybinds panel. Changes are batched into one redraw per frame.
local KeybindEntries = {}
local keybindRefreshPending = false
local function refreshKeybinds()
	if keybindRefreshPending then
		return
	end
	keybindRefreshPending = true
	task.defer(function()
		keybindRefreshPending = false
		if Library._renderKeybinds and not Library.Unloaded then
			Library._renderKeybinds()
		end
	end)
end

-- Key chip shared by standalone keybinds and toggles.
-- opts.Mode: "Toggle" (flip state on press), "Hold" (on while held), "Press" (fire once).
-- opts.ShowInList = false keeps it out of the keybinds panel.
-- meta (internal): Label for the panel, and GetState() for whether its feature is on.
local function newKeybind(id, opts, parent, position, onPress, onRelease, meta)
	meta = meta or {}
	local option = newOption(id, "Keybind", opts)
	option.Value = parseKey(opts.Default)
	option.Mode = opts.Mode or "Toggle"
	option.State = false

	local entry = { Option = option, Label = meta.Label or opts.Text or id or "Keybind", Hidden = opts.ShowInList == false }
	entry.GetState = meta.GetState or function()
		if option.Mode == "Press" then
			return entry.PulseUntil ~= nil and os.clock() < entry.PulseUntil
		end
		return option.State
	end
	table.insert(KeybindEntries, entry)

	local picking = false
	local Chip = create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = position,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(0, 18),
		AutoButtonColor = false,
		FontFace = FONT_MEDIUM,
		TextSize = 11,
		Theme = { BackgroundColor3 = "Field", TextColor3 = "SubText" },
		Parent = parent,
	}, { corner(), stroke("BorderLight"), padding(0, 6, 0, 6) })

	local function display()
		Chip.Text = picking and "..." or keyName(option.Value)
	end
	display()

	-- A keybind's Callback fires on activation; OnChanged fires when the key changes.
	function option:SetValue(key)
		self.Value = parseKey(key)
		display()
		for _, fn in ipairs(self.Changed) do
			fire(fn, self.Value)
		end
		refreshKeybinds()
	end

	Chip.MouseButton1Click:Connect(function()
		picking = true
		Library.Picking = true
		Chip.TextColor3 = Library.Theme.Accent
		display()
	end)

	connect(UserInputService.InputBegan, function(input, processed)
		if picking then
			local kind = input.UserInputType
			if kind == Enum.UserInputType.Keyboard then
				option:SetValue(input.KeyCode ~= Enum.KeyCode.Escape and input.KeyCode or nil)
			elseif kind == Enum.UserInputType.MouseButton2 or kind == Enum.UserInputType.MouseButton3 then
				option:SetValue(kind)
			elseif kind ~= Enum.UserInputType.MouseButton1 then
				return
			end
			picking = false
			Chip.TextColor3 = Library.Theme.SubText
			display()
			task.defer(function()
				Library.Picking = false
			end)
			return
		end

		if processed or Library.Picking or not inputMatches(input, option.Value) then
			return
		end
		if option.Mode == "Toggle" then
			option.State = not option.State
			fire(opts.Callback, option.State)
		elseif option.Mode == "Hold" then
			option.State = true
			fire(opts.Callback, true)
		else
			fire(opts.Callback)
			entry.PulseUntil = os.clock() + 0.3
			task.delay(0.32, refreshKeybinds)
		end
		if onPress then
			onPress()
		end
		refreshKeybinds()
	end)

	connect(UserInputService.InputEnded, function(input)
		if option.Mode == "Hold" and option.State and inputMatches(input, option.Value) then
			option.State = false
			fire(opts.Callback, false)
			if onRelease then
				onRelease()
			end
			refreshKeybinds()
		end
	end)

	return option
end

--// Groupbox elements

local Elements = {}
Elements.__index = Elements

function Elements:_next()
	self.Order = self.Order + 1
	return self.Order
end

function Elements:_holder(height)
	return create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, height or 0),
		AutomaticSize = height and Enum.AutomaticSize.None or Enum.AutomaticSize.Y,
		LayoutOrder = self:_next(),
		Parent = self.Container,
	})
end

-- flashTarget: what search outlines (must be a GuiObject without its own UIStroke).
function Elements:_index(name, holder, flashTarget)
	table.insert(SearchIndex, { Name = name, Holder = holder, Flash = flashTarget, Tab = self.Tab, Column = self.Column, Group = self })
end

function Elements:AddLabel(content, wrap)
	local Label = text({
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = content or "",
		TextWrapped = wrap ~= false,
		RichText = true,
		LayoutOrder = self:_next(),
		Theme = { TextColor3 = "SubText" },
		Parent = self.Container,
	})
	local object = {}
	function object:SetText(newText)
		Label.Text = newText
	end
	return object
end

function Elements:AddDivider()
	create("Frame", {
		Size = UDim2.new(1, 0, 0, 1),
		LayoutOrder = self:_next(),
		Theme = { BackgroundColor3 = "Border" },
		Parent = self.Container,
	})
end

function Elements:AddButton(opts, func)
	if type(opts) == "string" then
		opts = { Text = opts, Func = func }
	end
	local Holder = self:_holder(26)
	local Edge = stroke("BorderLight")
	local Button = create("TextButton", {
		Size = UDim2.fromScale(1, 1),
		AutoButtonColor = false,
		FontFace = FONT_MEDIUM,
		TextSize = 13,
		Text = opts.Text or "Button",
		Theme = { BackgroundColor3 = "Button", TextColor3 = "Text" },
		Parent = Holder,
	}, { corner(), Edge })

	Button.MouseEnter:Connect(function()
		tween(Edge, { Color = Library.Theme.Accent })
	end)
	Button.MouseLeave:Connect(function()
		tween(Edge, { Color = Library.Theme.BorderLight })
	end)
	Button.MouseButton1Click:Connect(function()
		Button.BackgroundColor3 = Library.Theme.Accent
		tween(Button, { BackgroundColor3 = Library.Theme.Button }, TweenInfo.new(0.3, Enum.EasingStyle.Quad))
		fire(opts.Func)
	end)
	attachTooltip(Button, opts.Tooltip)
	self:_index(opts.Text or "Button", Holder, Holder)

	local object = {}
	function object:SetText(newText)
		Button.Text = newText
	end
	return object
end

function Elements:AddToggle(id, opts)
	local option = newOption(id, "Toggle", opts)
	option.Value = opts.Default == true

	local Holder = self:_holder(20)
	local Row = create("TextButton", {
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Text = "",
		AutoButtonColor = false,
		Parent = Holder,
	})

	-- Checkbox on the left; it fills with the accent when on.
	local BoxEdge = stroke("BorderLight")
	local Box = create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(14, 14),
		Parent = Row,
	}, { corner(4), BoxEdge })
	local Label = text({
		Position = UDim2.fromOffset(22, 0),
		Size = UDim2.new(1, -22, 1, 0),
		Text = opts.Text or id,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = false,
		Parent = Row,
	})

	local function paint(animated)
		local T = Library.Theme
		local on = option.Value
		local goals = {
			[Box] = { BackgroundColor3 = on and T.Accent or T.Field },
			[BoxEdge] = { Color = on and T.Accent or T.BorderLight },
			[Label] = { TextColor3 = on and T.Text or T.SubText },
		}
		for instance, props in pairs(goals) do
			if animated then
				tween(instance, props)
			else
				for property, value in pairs(props) do
					instance[property] = value
				end
			end
		end
	end
	table.insert(ThemeCallbacks, function()
		paint(false)
	end)
	paint(false)

	function option:SetValue(value)
		value = value == true
		if value == self.Value then
			return
		end
		self.Value = value
		paint(true)
		self:_emit()
		refreshKeybinds()
	end

	-- Adds a key chip on the right that flips (or, in Hold mode, holds) the toggle.
	function option:AddKeybind(keyId, keyOpts)
		keyOpts = keyOpts or {}
		Label.Size = UDim2.new(1, -100, 1, 0)
		return newKeybind(keyId, keyOpts, Row, UDim2.new(1, 0, 0.5, 0), function()
			if keyOpts.Mode == "Hold" then
				option:SetValue(true)
			else
				option:SetValue(not option.Value)
			end
		end, function()
			option:SetValue(false)
		end, {
			Label = opts.Text or id,
			GetState = function()
				return option.Value
			end,
		})
	end

	Row.MouseEnter:Connect(function()
		if not option.Value then
			tween(Label, { TextColor3 = Library.Theme.Text })
		end
	end)
	Row.MouseLeave:Connect(function()
		paint(true)
	end)
	Row.MouseButton1Click:Connect(function()
		option:SetValue(not option.Value)
	end)
	attachTooltip(Row, opts.Tooltip)
	self:_index(opts.Text or id, Holder, Holder)
	return option
end

function Elements:AddSlider(id, opts)
	local option = newOption(id, "Slider", opts)
	local min, max = opts.Min or 0, opts.Max or 100
	local rounding = opts.Rounding or 0
	local suffix = opts.Suffix or ""

	local function round(value)
		local m = 10 ^ rounding
		return math.floor(value * m + 0.5) / m
	end
	option.Value = math.clamp(round(opts.Default or min), min, max)

	local Holder = self:_holder(34)
	text({ Size = UDim2.new(1, -70, 0, 16), Text = opts.Text or id, TextTruncate = Enum.TextTruncate.AtEnd, Parent = Holder })
	local Value = text({
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.fromScale(1, 0),
		Size = UDim2.fromOffset(70, 16),
		FontFace = FONT_MEDIUM,
		TextXAlignment = Enum.TextXAlignment.Right,
		Theme = { TextColor3 = "Accent" },
		Parent = Holder,
	})
	local Track = create("Frame", {
		Position = UDim2.fromOffset(0, 23),
		Size = UDim2.new(1, 0, 0, 6),
		Theme = { BackgroundColor3 = "Field" },
		Parent = Holder,
	}, { corner(), stroke("BorderLight") })
	local Fill = create("Frame", { Theme = { BackgroundColor3 = "Accent" }, Parent = Track }, { corner() })
	local Hit = create("TextButton", {
		BackgroundTransparency = 1,
		Text = "",
		Position = UDim2.fromOffset(0, 16),
		Size = UDim2.new(1, 0, 0, 18),
		Parent = Holder,
	})

	local function display(instant)
		local pct = max == min and 0 or (option.Value - min) / (max - min)
		Value.Text = string.format("%." .. rounding .. "f", option.Value) .. suffix
		if instant then
			Fill.Size = UDim2.fromScale(pct, 1)
		else
			tween(Fill, { Size = UDim2.fromScale(pct, 1) }, TWEEN_FAST)
		end
	end

	function option:SetValue(value)
		value = math.clamp(round(tonumber(value) or min), min, max)
		if value == self.Value then
			return
		end
		self.Value = value
		display(false)
		self:_emit()
	end

	local dragging = false
	local function update(x)
		local pct = math.clamp((x - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
		option:SetValue(min + (max - min) * pct)
	end
	Hit.InputBegan:Connect(function(input)
		if isPointer(input) then
			dragging = true
			update(input.Position.X)
		end
	end)
	connect(UserInputService.InputChanged, function(input)
		if dragging and isMove(input) then
			update(input.Position.X)
		end
	end)
	connect(UserInputService.InputEnded, function(input)
		if isPointer(input) then
			dragging = false
		end
	end)

	display(true)
	self:_index(opts.Text or id, Holder, Holder)
	return option
end

function Elements:AddDropdown(id, opts)
	local option = newOption(id, "Dropdown", opts)
	option.Values = opts.Values or {}

	local function resolve(value)
		if type(value) == "number" then
			return option.Values[value]
		end
		return value
	end
	option.Value = resolve(opts.Default)

	local Holder = self:_holder()
	list(5).Parent = Holder
	if opts.Text then
		text({ Size = UDim2.new(1, 0, 0, 16), Text = opts.Text, LayoutOrder = 1, Parent = Holder })
	end

	local FieldEdge = stroke("BorderLight")
	local Field = create("TextButton", {
		Size = UDim2.new(1, 0, 0, 26),
		AutoButtonColor = false,
		Text = "",
		LayoutOrder = 2,
		Theme = { BackgroundColor3 = "Field" },
		Parent = Holder,
	}, { corner(), FieldEdge })
	local Selected = text({
		Position = UDim2.fromOffset(9, 0),
		Size = UDim2.new(1, -32, 1, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = false,
		Parent = Field,
	})
	local Chevron = text({
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -9, 0.5, 0),
		Size = UDim2.fromOffset(10, 10),
		FontFace = FONT_BOLD,
		TextSize = 15,
		Text = "›",
		Rotation = 90,
		TextXAlignment = Enum.TextXAlignment.Center,
		Theme = { TextColor3 = "Muted" },
		Parent = Field,
	})

	local Panel = create("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
		LayoutOrder = 3,
		Theme = { BackgroundColor3 = "Chrome" },
		Parent = Holder,
	}, { corner(), stroke("BorderLight"), padding(3), list(1) })

	local Filter
	if opts.Searchable then
		Filter = create("TextBox", {
			Size = UDim2.new(1, 0, 0, 24),
			Text = "",
			PlaceholderText = "Filter",
			ClearTextOnFocus = false,
			FontFace = FONT,
			TextSize = 13,
			TextXAlignment = Enum.TextXAlignment.Left,
			LayoutOrder = 1,
			Theme = { BackgroundColor3 = "Background", TextColor3 = "Text", PlaceholderColor3 = "Muted" },
			Parent = Panel,
		}, { corner(), padding(0, 8, 0, 8) })
	end

	local ListFrame = create("ScrollingFrame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		LayoutOrder = 2,
		Theme = { ScrollBarImageColor3 = "BorderLight" },
		Parent = Panel,
	}, { list(1) })

	local items = {}
	local open = false

	local function display()
		local T = Library.Theme
		if option.Value ~= nil then
			Selected.Text = tostring(option.Value)
			Selected.TextColor3 = T.Text
		else
			Selected.Text = opts.Placeholder or "Select"
			Selected.TextColor3 = T.Muted
		end
	end

	local function paintItems()
		local T = Library.Theme
		for _, item in ipairs(items) do
			local selected = item.Value == option.Value
			item.Button.BackgroundColor3 = T.Hover
			item.Button.TextColor3 = selected and T.Accent or T.SubText
			item.Bar.Visible = selected
		end
	end

	local setOpen

	local function rebuild()
		for _, item in ipairs(items) do
			item.Button:Destroy()
		end
		items = {}
		local query = Filter and Filter.Text:lower() or ""
		for index, value in ipairs(option.Values) do
			local label = tostring(value)
			if query == "" or label:lower():find(query, 1, true) then
				local Item = create("TextButton", {
					Size = UDim2.new(1, 0, 0, 24),
					BackgroundTransparency = 1,
					AutoButtonColor = false,
					FontFace = FONT,
					TextSize = 13,
					Text = label,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					LayoutOrder = index,
					Parent = ListFrame,
				}, { corner(), padding(0, 8, 0, 10) })
				local Bar = create("Frame", {
					AnchorPoint = Vector2.new(0, 0.5),
					Position = UDim2.new(0, -10, 0.5, 0),
					Size = UDim2.fromOffset(2, 12),
					Theme = { BackgroundColor3 = "Accent" },
					Parent = Item,
				})
				Item.MouseEnter:Connect(function()
					Item.BackgroundTransparency = 0
				end)
				Item.MouseLeave:Connect(function()
					Item.BackgroundTransparency = 1
				end)
				Item.MouseButton1Click:Connect(function()
					option:SetValue(value)
					setOpen(false)
				end)
				table.insert(items, { Button = Item, Bar = Bar, Value = value })
			end
		end
		ListFrame.Size = UDim2.new(1, 0, 0, math.max(1, math.min(#items, opts.MaxVisible or 6)) * 25)
		paintItems()
	end

	setOpen = function(state)
		open = state
		Panel.Visible = state
		Chevron.Rotation = state and -90 or 90
		FieldEdge.Color = state and Library.Theme.Accent or Library.Theme.BorderLight
		if state then
			if Filter then
				Filter.Text = ""
			end
			rebuild()
		end
	end

	Field.MouseButton1Click:Connect(function()
		setOpen(not open)
	end)
	Field.MouseEnter:Connect(function()
		if not open then
			tween(FieldEdge, { Color = Library.Theme.Muted })
		end
	end)
	Field.MouseLeave:Connect(function()
		if not open then
			tween(FieldEdge, { Color = Library.Theme.BorderLight })
		end
	end)
	if Filter then
		Filter:GetPropertyChangedSignal("Text"):Connect(function()
			if open then
				rebuild()
			end
		end)
	end

	function option:SetValue(value)
		value = resolve(value)
		if value == self.Value then
			return
		end
		self.Value = value
		display()
		paintItems()
		self:_emit()
	end

	function option:SetValues(values)
		self.Values = values or {}
		if self.Value ~= nil and not table.find(self.Values, self.Value) then
			self.Value = nil
			display()
		end
		if open then
			rebuild()
		end
	end

	table.insert(ThemeCallbacks, function()
		display()
		paintItems()
	end)
	display()
	attachTooltip(Field, opts.Tooltip)
	self:_index(opts.Text or id, Holder, Selected)
	return option
end

function Elements:AddInput(id, opts)
	local option = newOption(id, "Input", opts)
	option.Value = tostring(opts.Default or "")

	local Holder = self:_holder()
	list(5).Parent = Holder
	if opts.Text then
		text({ Size = UDim2.new(1, 0, 0, 16), Text = opts.Text, LayoutOrder = 1, Parent = Holder })
	end

	local Edge = stroke("BorderLight")
	local Box = create("TextBox", {
		Size = UDim2.new(1, 0, 0, 26),
		Text = option.Value,
		PlaceholderText = opts.Placeholder or "",
		ClearTextOnFocus = opts.ClearTextOnFocus == true,
		ClipsDescendants = true,
		FontFace = FONT,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 2,
		Theme = { BackgroundColor3 = "Field", TextColor3 = "Text", PlaceholderColor3 = "Muted" },
		Parent = Holder,
	}, { corner(), Edge, padding(0, 9, 0, 9) })

	function option:SetValue(value)
		value = tostring(value or "")
		if opts.Numeric and value ~= "" and not tonumber(value) then
			Box.Text = self.Value
			return
		end
		Box.Text = value
		if value == self.Value then
			return
		end
		self.Value = value
		self:_emit()
	end

	Box.Focused:Connect(function()
		tween(Edge, { Color = Library.Theme.Accent })
	end)
	Box.FocusLost:Connect(function()
		tween(Edge, { Color = Library.Theme.BorderLight })
		if opts.Finished then
			option:SetValue(Box.Text)
		end
	end)
	if not opts.Finished then
		Box:GetPropertyChangedSignal("Text"):Connect(function()
			option:SetValue(Box.Text)
		end)
	end
	self:_index(opts.Text or id, Holder, Holder)
	return option
end

function Elements:AddKeybind(id, opts)
	local Holder = self:_holder(20)
	text({ Size = UDim2.new(1, -100, 1, 0), Text = opts.Text or id, TextTruncate = Enum.TextTruncate.AtEnd, Parent = Holder })
	self:_index(opts.Text or id, Holder, Holder)
	return newKeybind(id, opts, Holder, UDim2.new(1, 0, 0.5, 0))
end

-- Bordered box with its title set into the top border, like a fieldset.
local function newGroupbox(tab, column, title)
	local Outer = create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = #column:GetChildren(),
		Parent = column,
	})
	local BoxPadding = padding(17, 12, 12, 12)
	local Box = create("Frame", {
		Position = UDim2.fromOffset(0, 7),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = { BackgroundColor3 = "Background" },
		Parent = Outer,
	}, { corner(), stroke("Border"), BoxPadding })
	local Content = create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = Box,
	}, { list(9) })
	-- The legend sits on the border line; its background matches the box so it cuts a gap in the border.
	local Legend = text({
		Position = UDim2.fromOffset(9, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(0, 14),
		FontFace = FONT_BOLD,
		TextSize = 11,
		Text = string.upper(title or ""),
		BackgroundTransparency = 0,
		Theme = { BackgroundColor3 = "Background", TextColor3 = "SubText" },
		Parent = Outer,
	})
	padding(0, 4, 0, 4).Parent = Legend

	-- Collapse button, also set into the border (right side), drawn as a minus / plus.
	local Collapse = create("TextButton", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -8, 0, 0),
		Size = UDim2.fromOffset(18, 14),
		AutoButtonColor = false,
		Text = "",
		Theme = { BackgroundColor3 = "Background" },
		Parent = Outer,
	})
	local Across = create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(8, 2),
		Theme = { BackgroundColor3 = "Muted" },
		Parent = Collapse,
	})
	local Down = create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(2, 8),
		Visible = false,
		Theme = { BackgroundColor3 = "Muted" },
		Parent = Collapse,
	})

	local group = setmetatable({ Container = Content, Order = 0, Tab = tab, Column = column }, Elements)
	local function setCollapsed(collapsed)
		Content.Visible = not collapsed
		Down.Visible = collapsed
		BoxPadding.PaddingBottom = UDim.new(0, collapsed and 0 or 12)
		BoxPadding.PaddingTop = UDim.new(0, collapsed and 13 or 17)
	end
	function group.Expand()
		setCollapsed(false)
	end
	Collapse.MouseButton1Click:Connect(function()
		setCollapsed(Content.Visible)
	end)
	Collapse.MouseEnter:Connect(function()
		Across.BackgroundColor3, Down.BackgroundColor3 = Library.Theme.Text, Library.Theme.Text
	end)
	Collapse.MouseLeave:Connect(function()
		Across.BackgroundColor3, Down.BackgroundColor3 = Library.Theme.Muted, Library.Theme.Muted
	end)

	return group
end

--// Active keybinds panel: stays on screen while the menu is hidden

local function buildKeybindPanel(ScreenGui)
	local Panel = create("Frame", {
		Position = UDim2.new(0, 16, 0.38, 0),
		Size = UDim2.fromOffset(200, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
		Theme = { BackgroundColor3 = "Background" },
		Parent = ScreenGui,
	}, { corner(), stroke("Border") })
	Library.PanelScale = create("UIScale", { Scale = Library.UserScale, Parent = Panel })
	create("Frame", { Position = UDim2.fromOffset(RADIUS, 0), Size = UDim2.new(1, -2 * RADIUS, 0, 2), Theme = { BackgroundColor3 = "Accent" }, Parent = Panel })
	text({ Position = UDim2.fromOffset(12, 2), Size = UDim2.new(1, -24, 0, 28), FontFace = FONT_BOLD, TextSize = 12, Text = "Keybinds", Parent = Panel })
	create("Frame", { Position = UDim2.fromOffset(0, 30), Size = UDim2.new(1, 0, 0, 1), Theme = { BackgroundColor3 = "Border" }, Parent = Panel })
	local Rows = create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, 31),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = Panel,
	}, { list(2), padding(6, 12, 8, 12) })

	-- Drag by the header.
	local dragging, dragStart, startPos
	Panel.InputBegan:Connect(function(input)
		if isPointer(input) and input.Position.Y - Panel.AbsolutePosition.Y <= 30 * Library.PanelScale.Scale then
			dragging, dragStart, startPos = true, input.Position, Panel.Position
		end
	end)
	connect(UserInputService.InputChanged, function(input)
		if dragging and isMove(input) then
			local delta = input.Position - dragStart
			Panel.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)
	connect(UserInputService.InputEnded, function(input)
		if isPointer(input) then
			dragging = false
		end
	end)

	local rows = {}
	function Library._renderKeybinds()
		for _, row in ipairs(rows) do
			row:Destroy()
		end
		rows = {}
		local T = Library.Theme
		for index, entry in ipairs(KeybindEntries) do
			if not entry.Hidden and entry.Option.Value then
				local active = entry.GetState() == true
				local Row = create("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20), LayoutOrder = index, Parent = Rows })
				create("Frame", {
					AnchorPoint = Vector2.new(0, 0.5),
					Position = UDim2.fromScale(0, 0.5),
					Size = UDim2.fromOffset(8, 8),
					BackgroundColor3 = active and T.Accent or T.Field,
					Parent = Row,
				}, {
					corner(2),
					create("UIStroke", { ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Thickness = 1, Color = active and T.Accent or T.BorderLight }),
				})
				text({
					Position = UDim2.fromOffset(16, 0),
					Size = UDim2.new(1, -76, 1, 0),
					Text = entry.Label,
					TextTruncate = Enum.TextTruncate.AtEnd,
					TextColor3 = active and T.Text or T.SubText,
					Theme = false,
					Parent = Row,
				})
				local Key = text({
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.fromScale(1, 0.5),
					AutomaticSize = Enum.AutomaticSize.X,
					Size = UDim2.fromOffset(0, 16),
					FontFace = FONT_MEDIUM,
					TextSize = 11,
					Text = keyName(entry.Option.Value),
					BackgroundTransparency = 0,
					BackgroundColor3 = T.Field,
					TextColor3 = active and T.Accent or T.Muted,
					Theme = false,
					Parent = Row,
				})
				corner(4).Parent = Key
				padding(0, 6, 0, 6).Parent = Key
				table.insert(rows, Row)
			end
		end
		Panel.Visible = Library.KeybindListEnabled and #rows > 0
	end
	table.insert(ThemeCallbacks, refreshKeybinds)
	refreshKeybinds()
end

function Library:SetKeybindList(enabled)
	self.KeybindListEnabled = enabled
	refreshKeybinds()
end

--// Window

function Library:CreateWindow(info)
	info = info or {}
	local camera = workspace.CurrentCamera
	local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
	local width = math.min(info.Width or 820, viewport.X - 24)
	local height = math.min(info.Height or 560, viewport.Y - 24)

	self.Title = info.Title or "Kompile"
	self.ToggleKey = parseKey(info.ToggleKey or "RightShift")

	local ScreenGui = create("ScreenGui", {
		Name = "Kompile",
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 999,
	})
	parentGui(ScreenGui)
	self.ScreenGui = ScreenGui

	local Main = create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(width, height),
		Visible = false, -- Window:Toggle(true) at the end fades it in
		Theme = { BackgroundColor3 = "Background" },
		Parent = ScreenGui,
	}, { corner(WINDOW_RADIUS), stroke("Border") })
	self.Scale = create("UIScale", { Scale = self.UserScale, Parent = Main })

	-- Subtle purple glow around the window: stacked outlines that fade outward (Roblox has no real
	-- blur), with a brighter section that slowly travels around the edge.
	local Glow = create("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = Main })
	local glowGradients = {}
	for _, layer in ipairs({ { 1.5, 0.62 }, { 4, 0.82 }, { 8, 0.9 }, { 13, 0.95 } }) do
		local gradient = create("UIGradient", {
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.45, 0.72),
				NumberSequenceKeypoint.new(1, 0.72),
			}),
		})
		create("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = Glow }, {
			corner(WINDOW_RADIUS + 1),
			create("UIStroke", {
				ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				Thickness = layer[1],
				Transparency = layer[2],
				Theme = { Color = "Accent" },
			}, { gradient }),
		})
		table.insert(glowGradients, gradient)
	end
	connect(RunService.RenderStepped, function()
		if Glow.Visible and Main.Visible then
			local rotation = (os.clock() * 40) % 360
			for _, gradient in ipairs(glowGradients) do
				gradient.Rotation = rotation
			end
		end
	end)
	Glow.Visible = self.GlowEnabled

	function Library:SetGlow(enabled)
		self.GlowEnabled = enabled
		Glow.Visible = enabled
	end

	-- Accent strip across the top, inset so it starts and ends where the rounded corners begin.
	create("Frame", { Position = UDim2.fromOffset(WINDOW_RADIUS, 0), Size = UDim2.new(1, -2 * WINDOW_RADIUS, 0, 2), Theme = { BackgroundColor3 = "Accent" }, Parent = Main })

	-- Sidebar: K_ mark with the title and subtitle, numbered tabs, you at the bottom
	local Sidebar = create("Frame", {
		Position = UDim2.fromOffset(0, STRIP),
		Size = UDim2.new(0, SIDEBAR, 1, -(STRIP + STATUSBAR)),
		Theme = { BackgroundColor3 = "Chrome" },
		Parent = Main,
	}, {
		corner(WINDOW_RADIUS),
		-- Square off every corner except the window's top-left.
		create("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.new(0, WINDOW_RADIUS, 1, 0), Theme = { BackgroundColor3 = "Chrome" } }),
		create("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.new(1, 0, 0, WINDOW_RADIUS), Theme = { BackgroundColor3 = "Chrome" } }),
	})
	create("Frame", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.new(0, 1, 1, 0), Theme = { BackgroundColor3 = "Border" }, Parent = Sidebar })

	text({ Position = UDim2.fromOffset(14, 11), Size = UDim2.fromOffset(16, 26), FontFace = FONT_BOLD, TextSize = 24, Text = "K", Theme = { TextColor3 = "Accent" }, Parent = Sidebar })
	local Cursor = create("Frame", {
		Position = UDim2.fromOffset(30, 31),
		Size = UDim2.fromOffset(8, 3),
		Theme = { BackgroundColor3 = "Text" },
		Parent = Sidebar,
	})
	task.spawn(function()
		while not Library.Unloaded do
			task.wait(0.55)
			Cursor.BackgroundTransparency = Cursor.BackgroundTransparency == 0 and 1 or 0
		end
	end)
	text({ Position = UDim2.fromOffset(46, 11), Size = UDim2.new(1, -52, 0, 16), FontFace = FONT_BOLD, TextSize = 14, Text = self.Title, Parent = Sidebar })
	text({
		Position = UDim2.fromOffset(46, 27),
		Size = UDim2.new(1, -52, 0, 14),
		TextSize = 11,
		Text = info.Subtitle or "script hub",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = { TextColor3 = "Muted" },
		Parent = Sidebar,
	})
	create("Frame", { Position = UDim2.fromOffset(12, HEADER), Size = UDim2.new(1, -25, 0, 1), Theme = { BackgroundColor3 = "Border" }, Parent = Sidebar })

	local TabList = create("ScrollingFrame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, HEADER + 8),
		Size = UDim2.new(1, -1, 1, -(HEADER + 8 + 44)),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 0,
		Parent = Sidebar,
	}, { list(2), padding(0, 8, 0, 8) })

	local Me = create("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, -1, 0, 42),
		Parent = Sidebar,
	})
	create("Frame", { Size = UDim2.new(1, 0, 0, 1), Theme = { BackgroundColor3 = "Border" }, Parent = Me })
	local Avatar = create("ImageLabel", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 12, 0.5, 0),
		Size = UDim2.fromOffset(22, 22),
		Theme = { BackgroundColor3 = "Button" },
		Parent = Me,
	}, { corner(11) })
	task.spawn(function()
		local ok, image = pcall(function()
			return Players:GetUserThumbnailAsync(LocalPlayer.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
		end)
		if ok then
			Avatar.Image = image
		end
	end)
	text({ Position = UDim2.fromOffset(42, 6), Size = UDim2.new(1, -50, 0, 15), FontFace = FONT_MEDIUM, Text = LocalPlayer.DisplayName, TextTruncate = Enum.TextTruncate.AtEnd, Parent = Me })
	text({ Position = UDim2.fromOffset(42, 21), Size = UDim2.new(1, -50, 0, 14), TextSize = 11, Text = "@" .. LocalPlayer.Name, TextTruncate = Enum.TextTruncate.AtEnd, Theme = { TextColor3 = "Muted" }, Parent = Me })

	-- Content: page title, pill search and hide button, then the pages
	local Content = create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(SIDEBAR, STRIP),
		Size = UDim2.new(1, -SIDEBAR, 1, -(STRIP + STATUSBAR)),
		Parent = Main,
	})
	local Header = text({ Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -270, 0, HEADER), FontFace = FONT_BOLD, TextSize = 18, Parent = Content })
	create("Frame", { Position = UDim2.fromOffset(0, HEADER), Size = UDim2.new(1, 0, 0, 1), Theme = { BackgroundColor3 = "Border" }, Parent = Content })

	local HideButton = create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0, HEADER / 2),
		Size = UDim2.fromOffset(26, 26),
		AutoButtonColor = false,
		Text = "",
		Theme = { BackgroundColor3 = "Field" },
		Parent = Content,
	}, { corner(), stroke("BorderLight") })
	local HideBar = create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(10, 2),
		Theme = { BackgroundColor3 = "SubText" },
		Parent = HideButton,
	})
	HideButton.MouseEnter:Connect(function()
		HideBar.BackgroundColor3 = Library.Theme.Text
	end)
	HideButton.MouseLeave:Connect(function()
		HideBar.BackgroundColor3 = Library.Theme.SubText
	end)

	local SearchEdge = stroke("BorderLight")
	local SearchField = create("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -46, 0, HEADER / 2),
		Size = UDim2.fromOffset(190, 26),
		Theme = { BackgroundColor3 = "Field" },
		Parent = Content,
	}, { corner(13), SearchEdge })
	-- Magnifier drawn from a ring and a handle.
	create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(11, 8),
		Size = UDim2.fromOffset(9, 9),
		Parent = SearchField,
	}, { corner(5), create("UIStroke", { Thickness = 1.4, Theme = { Color = "Muted" } }) })
	create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromOffset(21.5, 18.5),
		Size = UDim2.fromOffset(1.5, 4.5),
		Rotation = -45,
		Theme = { BackgroundColor3 = "Muted" },
		Parent = SearchField,
	})
	local SearchBox = create("TextBox", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(29, 0),
		Size = UDim2.new(1, -40, 1, 0),
		Text = "",
		PlaceholderText = "Search",
		ClearTextOnFocus = false,
		FontFace = FONT,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		Theme = { TextColor3 = "Text", PlaceholderColor3 = "Muted" },
		Parent = SearchField,
	})

	local Pages = create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, HEADER + 1),
		Size = UDim2.new(1, 0, 1, -(HEADER + 1)),
		ClipsDescendants = true,
		Parent = Content,
	})

	-- Status bar: menu key chip, footer in the middle, FPS/ping with a small graph on the right
	local StatusBar = create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, STATUSBAR),
		Theme = { BackgroundColor3 = "Chrome" },
		Parent = Main,
	}, { corner(WINDOW_RADIUS) })
	create("Frame", { Size = UDim2.new(1, 0, 0, WINDOW_RADIUS), Theme = { BackgroundColor3 = "Chrome" }, Parent = StatusBar })
	create("Frame", { Size = UDim2.new(1, 0, 0, 1), Theme = { BackgroundColor3 = "Border" }, Parent = StatusBar })

	local KeyChip = create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 10, 0.5, 0),
		Size = UDim2.fromOffset(0, 16),
		AutomaticSize = Enum.AutomaticSize.X,
		Theme = { BackgroundColor3 = "Field" },
		Parent = StatusBar,
	}, { corner(), stroke("BorderLight"), list(5, true, { VerticalAlignment = Enum.VerticalAlignment.Center }), padding(0, 7, 0, 7) })
	text({ AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 14), TextSize = 11, Text = "Menu", LayoutOrder = 1, Theme = { TextColor3 = "Muted" }, Parent = KeyChip })
	local KeyLabel = text({ AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 14), FontFace = FONT_SEMI, TextSize = 11, LayoutOrder = 2, Parent = KeyChip })

	local Center = create("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(0, 14),
		AutomaticSize = Enum.AutomaticSize.X,
		Parent = StatusBar,
	}, { list(6, true, { VerticalAlignment = Enum.VerticalAlignment.Center }) })
	create("Frame", { Size = UDim2.fromOffset(5, 5), LayoutOrder = 1, Theme = { BackgroundColor3 = "Accent" }, Parent = Center })
	text({ AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 14), TextSize = 11, Text = info.Footer or self.Title, LayoutOrder = 2, Theme = { TextColor3 = "Muted" }, Parent = Center })

	local GRAPH_BARS, GRAPH_HEIGHT = 16, 12
	local Graph = create("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		Size = UDim2.fromOffset(GRAPH_BARS * 3 - 1, GRAPH_HEIGHT),
		Parent = StatusBar,
	})
	local bars, history = {}, {}
	for index = 1, GRAPH_BARS do
		bars[index] = create("Frame", {
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, (index - 1) * 3, 1, 0),
			Size = UDim2.fromOffset(2, 2),
			Theme = { BackgroundColor3 = "BorderLight" },
			Parent = Graph,
		})
		history[index] = 0
	end
	local FpsLabel = text({
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -(10 + GRAPH_BARS * 3 + 8), 0, 0),
		Size = UDim2.new(0, 140, 1, 0),
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Right,
		Theme = { TextColor3 = "Muted" },
		Parent = StatusBar,
	})

	local fps, ping = 0, 0
	local function paintStatus()
		KeyLabel.Text = keyName(Library.ToggleKey)
		FpsLabel.Text = fps .. " FPS  ·  " .. ping .. " ms"
		local peak = 60
		for _, value in ipairs(history) do
			peak = math.max(peak, value)
		end
		for index, bar in ipairs(bars) do
			local value = history[index]
			bar.Size = UDim2.fromOffset(2, math.max(2, math.floor(GRAPH_HEIGHT * value / peak + 0.5)))
			bar.BackgroundColor3 = index == GRAPH_BARS and Library.Theme.Text or (value > 0 and Library.Theme.Accent or Library.Theme.BorderLight)
		end
	end
	table.insert(ThemeCallbacks, paintStatus)
	paintStatus()

	local frames = 0
	connect(RunService.RenderStepped, function()
		frames = frames + 1
	end)
	task.spawn(function()
		while not Library.Unloaded do
			task.wait(0.5)
			fps = frames * 2
			frames = 0
			table.remove(history, 1)
			table.insert(history, fps)
			local ok, seconds = pcall(function()
				return LocalPlayer:GetNetworkPing()
			end)
			ping = ok and math.floor(seconds * 1000 + 0.5) or 0
			paintStatus()
		end
	end)

	-- Search results, under the search field
	local Results = create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -46, 0, HEADER - 6),
		Size = UDim2.fromOffset(240, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
		ZIndex = 20,
		Theme = { BackgroundColor3 = "Chrome" },
		Parent = Content,
	}, { corner(), stroke("BorderLight"), padding(3), list(1) })

	buildKeybindPanel(ScreenGui)

	-- Notifications and tooltip
	self.NotifyHolder = create("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -16, 1, -16),
		Size = UDim2.new(0, 280, 1, -32),
		Parent = ScreenGui,
	}, { list(6, false, { VerticalAlignment = Enum.VerticalAlignment.Bottom }) })
	self.Tooltip = text({
		Visible = false,
		AutomaticSize = Enum.AutomaticSize.XY,
		Size = UDim2.new(),
		BackgroundTransparency = 0,
		TextSize = 12,
		ZIndex = 50,
		Theme = { BackgroundColor3 = "Chrome", TextColor3 = "SubText" },
		Parent = ScreenGui,
	})
	corner().Parent = self.Tooltip
	stroke("BorderLight").Parent = self.Tooltip
	padding(4, 8, 4, 8).Parent = self.Tooltip

	local Window = { Tabs = {}, Main = Main }

	-- Quick fade on open and close. Every transparency in the window is tweened together
	-- (a CanvasGroup would clip the glow), then restored so the next fade starts clean.
	local FADE = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	local FADE_PROPS = {
		{ "GuiObject", "BackgroundTransparency" },
		{ "TextLabel", "TextTransparency" },
		{ "TextButton", "TextTransparency" },
		{ "TextBox", "TextTransparency" },
		{ "ImageLabel", "ImageTransparency" },
		{ "ImageButton", "ImageTransparency" },
		{ "ScrollingFrame", "ScrollBarImageTransparency" },
		{ "UIStroke", "Transparency" },
	}
	local open, fade, fadeId = false, nil, 0

	local function snapshot()
		local entries = {}
		local function add(instance)
			for _, pair in ipairs(FADE_PROPS) do
				if instance:IsA(pair[1]) and instance[pair[2]] < 1 then
					table.insert(entries, { instance, pair[2], instance[pair[2]] })
				end
			end
		end
		add(Main)
		for _, instance in ipairs(Main:GetDescendants()) do
			add(instance)
		end
		return entries
	end

	local function settle()
		if fade then
			for _, t in ipairs(fade.Tweens) do
				t:Cancel()
			end
			for _, entry in ipairs(fade.Entries) do
				entry[1][entry[2]] = entry[3]
			end
			fade = nil
		end
	end

	local function runFade(entries, toHidden, onDone)
		fadeId = fadeId + 1
		local id = fadeId
		local tweens = {}
		for _, entry in ipairs(entries) do
			if not toHidden then
				entry[1][entry[2]] = 1
			end
			table.insert(tweens, tween(entry[1], { [entry[2]] = toHidden and 1 or entry[3] }, FADE))
		end
		fade = { Entries = entries, Tweens = tweens }
		task.delay(FADE.Time, function()
			if id == fadeId then
				if onDone then
					onDone()
				end
				settle()
			end
		end)
	end

	function Window:Toggle(state)
		if state == nil then
			state = not open
		end
		if state == open then
			return
		end
		open = state
		settle()
		if state then
			Main.Visible = true
			runFade(snapshot(), false)
		else
			Library.Tooltip.Visible = false
			runFade(snapshot(), true, function()
				Main.Visible = false
			end)
		end
	end

	function Library:SetToggleKey(key)
		self.ToggleKey = parseKey(key)
		paintStatus()
	end

	HideButton.MouseButton1Click:Connect(function()
		Window:Toggle(false)
		Library:Notify("Kompile", "Menu hidden. Press " .. keyName(Library.ToggleKey) .. " to bring it back.")
	end)

	-- Drag by the header strip (the search box and buttons still work).
	local dragging, dragStart, startPos
	connect(Main.InputBegan, function(input)
		if isPointer(input) and input.Position.Y - Main.AbsolutePosition.Y <= (STRIP + HEADER) * scaleFactor() then
			dragging, dragStart, startPos = true, input.Position, Main.Position
		end
	end)
	connect(UserInputService.InputChanged, function(input)
		if dragging and isMove(input) then
			local delta = input.Position - dragStart
			Main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
		if Library.Tooltip.Visible and input.UserInputType == Enum.UserInputType.MouseMovement then
			Library.Tooltip.Position = UDim2.fromOffset(input.Position.X + 14, input.Position.Y + 16)
		end
	end)
	connect(UserInputService.InputEnded, function(input)
		if isPointer(input) then
			dragging = false
		end
	end)

	connect(UserInputService.InputBegan, function(input, processed)
		if not processed and not Library.Picking and inputMatches(input, Library.ToggleKey) then
			Window:Toggle()
		end
	end)

	if UserInputService.TouchEnabled then
		local MobileButton = create("TextButton", {
			Position = UDim2.fromOffset(16, 16),
			Size = UDim2.fromOffset(42, 42),
			AutoButtonColor = false,
			FontFace = FONT_BOLD,
			TextSize = 18,
			Text = "K",
			Theme = { BackgroundColor3 = "Chrome", TextColor3 = "Accent" },
			Parent = ScreenGui,
		}, { corner(), stroke("BorderLight") })
		MobileButton.MouseButton1Click:Connect(function()
			Window:Toggle()
		end)
	end

	-- Search across every control on every tab
	local resultButtons = {}
	local function reveal(entry)
		SearchBox.Text = ""
		Results.Visible = false
		entry.Tab:Select()
		if entry.Group and entry.Group.Expand then
			entry.Group.Expand()
		end
		task.delay(0.05, function()
			local column = entry.Column
			local s = scaleFactor()
			local y = (entry.Holder.AbsolutePosition.Y - column.AbsolutePosition.Y) / s + column.CanvasPosition.Y - 50
			column.CanvasPosition = Vector2.new(0, math.max(0, y))
			flash(entry.Flash)
		end)
	end

	local function runSearch()
		for _, button in ipairs(resultButtons) do
			button:Destroy()
		end
		resultButtons = {}
		local query = SearchBox.Text:lower()
		if query:match("^%s*$") then
			Results.Visible = false
			return
		end
		local matches = {}
		for _, entry in ipairs(SearchIndex) do
			if entry.Name:lower():find(query, 1, true) then
				table.insert(matches, entry)
				if #matches == 8 then
					break
				end
			end
		end
		Results.Visible = true
		if #matches == 0 then
			table.insert(resultButtons, text({ Size = UDim2.new(1, 0, 0, 24), Text = "  Nothing found", Theme = { TextColor3 = "Muted" }, Parent = Results }))
			return
		end
		for index, entry in ipairs(matches) do
			local Button = create("TextButton", {
				Size = UDim2.new(1, 0, 0, 24),
				BackgroundTransparency = index == 1 and 0 or 1,
				AutoButtonColor = false,
				Text = "",
				LayoutOrder = index,
				Theme = { BackgroundColor3 = "Hover" },
				Parent = Results,
			}, { corner() })
			text({ Position = UDim2.fromOffset(8, 0), Size = UDim2.new(0.62, -8, 1, 0), Text = entry.Name, TextTruncate = Enum.TextTruncate.AtEnd, Parent = Button })
			text({
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, -8, 0, 0),
				Size = UDim2.new(0.38, -8, 1, 0),
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Right,
				Text = entry.Tab.Name,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Theme = { TextColor3 = "Muted" },
				Parent = Button,
			})
			Button.MouseEnter:Connect(function()
				Button.BackgroundTransparency = 0
			end)
			Button.MouseLeave:Connect(function()
				Button.BackgroundTransparency = index == 1 and 0 or 1
			end)
			Button.MouseButton1Click:Connect(function()
				reveal(entry)
			end)
			table.insert(resultButtons, Button)
		end
		resultButtons.First = matches[1]
	end

	SearchBox:GetPropertyChangedSignal("Text"):Connect(runSearch)
	SearchBox.Focused:Connect(function()
		SearchEdge.Color = Library.Theme.Accent
		runSearch()
	end)
	SearchBox.FocusLost:Connect(function(enterPressed)
		SearchEdge.Color = Library.Theme.BorderLight
		if enterPressed and resultButtons.First then
			reveal(resultButtons.First)
			return
		end
		task.delay(0.2, function()
			if not SearchBox:IsFocused() then
				Results.Visible = false
			end
		end)
	end)

	function Window:AddTab(name)
		local selected = false
		local Button = create("TextButton", {
			Size = UDim2.new(1, 0, 0, 30),
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			LayoutOrder = #self.Tabs + 1,
			Theme = { BackgroundColor3 = "Hover" },
			Parent = TabList,
		}, { corner() })
		local Bar = create("Frame", {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 3, 0.5, 0),
			Size = UDim2.fromOffset(3, 14),
			Visible = false,
			Theme = { BackgroundColor3 = "Accent" },
			Parent = Button,
		}, { corner(2) })
		local Label = text({
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -44, 1, 0),
			FontFace = FONT_MEDIUM,
			Text = name,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Theme = false,
			Parent = Button,
		})
		local Number = text({
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 0),
			Size = UDim2.new(0, 24, 1, 0),
			FontFace = FONT_MEDIUM,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Right,
			Text = string.format("%02d", #self.Tabs + 1),
			Theme = false,
			Parent = Button,
		})

		local Page = create("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false, Parent = Pages })
		local function column(left)
			return create("ScrollingFrame", {
				BackgroundTransparency = 1,
				Position = left and UDim2.fromOffset(12, 0) or UDim2.new(0.5, 4, 0, 0),
				Size = UDim2.new(0.5, -16, 1, 0),
				CanvasSize = UDim2.new(),
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				ScrollingDirection = Enum.ScrollingDirection.Y,
				ScrollBarThickness = 2,
				Theme = { ScrollBarImageColor3 = "BorderLight" },
				Parent = Page,
			}, { list(12), padding(8, 4, 12, 1) })
		end
		local LeftColumn, RightColumn = column(true), column(false)

		local Tab = { Name = name }

		local function paint()
			local T = Library.Theme
			Button.BackgroundTransparency = selected and 0 or 1
			Bar.Visible = selected
			Label.TextColor3 = selected and T.Text or T.SubText
			Number.TextColor3 = selected and T.Accent or T.Muted
		end
		table.insert(ThemeCallbacks, paint)
		paint()

		function Tab:AddLeftGroupbox(title)
			return newGroupbox(Tab, LeftColumn, title)
		end
		function Tab:AddRightGroupbox(title)
			return newGroupbox(Tab, RightColumn, title)
		end

		function Tab:Select()
			for _, other in ipairs(Window.Tabs) do
				other._setSelected(other == Tab)
			end
			Header.Text = name
		end

		function Tab._setSelected(state)
			selected = state
			Page.Visible = state
			paint()
		end

		Button.MouseEnter:Connect(function()
			if not selected then
				Label.TextColor3 = Library.Theme.Text
			end
		end)
		Button.MouseLeave:Connect(paint)
		Button.MouseButton1Click:Connect(function()
			Tab:Select()
		end)

		table.insert(self.Tabs, Tab)
		if #self.Tabs == 1 then
			Tab:Select()
		end
		return Tab
	end

	self.Window = Window
	Window:Toggle(true)
	return Window
end

--// Notifications

function Library:Notify(title, description, duration)
	if type(title) == "table" then
		title, description, duration = title.Title, title.Description, title.Time
	elseif description == nil or type(description) == "number" then
		title, description, duration = self.Title or "Kompile", title, description
	end
	if not self.NotifyHolder then
		warn("[Kompile UI] " .. tostring(description))
		return
	end
	duration = duration or 4

	local Slot = create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		Parent = self.NotifyHolder,
	})
	local Card = create("Frame", {
		Position = UDim2.fromOffset(300, 0),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = { BackgroundColor3 = "Background" },
		Parent = Slot,
	}, { corner(), stroke("Border") })
	create("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 4, 0.5, 0), Size = UDim2.new(0, 3, 1, -16), Theme = { BackgroundColor3 = "Accent" }, Parent = Card }, { corner(2) })
	local Body = create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(12, 9),
		Size = UDim2.new(1, -22, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = Card,
	}, { list(2), padding(0, 0, 12, 0) })
	text({
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		FontFace = FONT_SEMI,
		Text = tostring(title),
		TextWrapped = true,
		LayoutOrder = 1,
		Parent = Body,
	})
	text({
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextSize = 12,
		Text = tostring(description or ""),
		TextWrapped = true,
		LayoutOrder = 2,
		Theme = { TextColor3 = "SubText" },
		Parent = Body,
	})
	local Progress = create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 12, 1, -4),
		Size = UDim2.new(1, -24, 0, 2),
		Theme = { BackgroundColor3 = "Accent" },
		Parent = Card,
	}, { corner(1) })

	-- The slot grows to the card's height so the stack slides instead of jumping.
	task.defer(function()
		tween(Slot, { Size = UDim2.new(1, 0, 0, Card.AbsoluteSize.Y) })
		tween(Card, { Position = UDim2.fromOffset(0, 0) }, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out))
		tween(Progress, { Size = UDim2.new(0, 0, 0, 2) }, TweenInfo.new(duration, Enum.EasingStyle.Linear))
	end)
	task.delay(duration, function()
		tween(Card, { Position = UDim2.fromOffset(300, 0) }, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In)).Completed:Wait()
		tween(Slot, { Size = UDim2.new(1, 0, 0, 0) }).Completed:Wait()
		Slot:Destroy()
	end)
end

--// Configs (need executor file functions)

local function hasFileApi()
	return type(writefile) == "function"
		and type(readfile) == "function"
		and type(isfile) == "function"
		and type(isfolder) == "function"
		and type(makefolder) == "function"
		and type(listfiles) == "function"
end

local function ensureFolder(path)
	local current = ""
	for part in path:gmatch("[^/]+") do
		current = current == "" and part or (current .. "/" .. part)
		if not isfolder(current) then
			makefolder(current)
		end
	end
end

local function cleanName(name)
	return (tostring(name or ""):gsub("[^%w%-_ ]", ""))
end

function Library:SetFolder(folder)
	self.Folder = folder
end

function Library:_configPath(name)
	return self.Folder .. "/configs/" .. name .. ".json"
end

function Library:SaveConfig(name)
	if not hasFileApi() then
		return false, "Your executor can't save files."
	end
	name = cleanName(name)
	if name == "" then
		return false, "Enter a config name first."
	end
	local data = {}
	for id, option in pairs(self.Options) do
		if option.Save then
			if option.Type == "Keybind" then
				data[id] = option.Value and option.Value.Name or "None"
			else
				data[id] = option.Value
			end
		end
	end
	ensureFolder(self.Folder .. "/configs")
	local ok, err = pcall(writefile, self:_configPath(name), HttpService:JSONEncode(data))
	if not ok then
		return false, tostring(err)
	end
	return true, name
end

function Library:LoadConfig(name)
	if not hasFileApi() then
		return false, "Your executor can't read files."
	end
	local path = self:_configPath(cleanName(name))
	if not isfile(path) then
		return false, "Config not found."
	end
	local ok, data = pcall(function()
		return HttpService:JSONDecode(readfile(path))
	end)
	if not ok or type(data) ~= "table" then
		return false, "That config file is corrupted."
	end
	for id, value in pairs(data) do
		local option = self.Options[id]
		if option and option.Save then
			pcall(option.SetValue, option, value)
		end
	end
	return true
end

function Library:DeleteConfig(name)
	if not hasFileApi() or type(delfile) ~= "function" then
		return false, "Your executor can't delete files."
	end
	local path = self:_configPath(cleanName(name))
	if not isfile(path) then
		return false, "Config not found."
	end
	delfile(path)
	return true
end

function Library:ListConfigs()
	local folder = self.Folder .. "/configs"
	if not hasFileApi() or not isfolder(folder) then
		return {}
	end
	local names = {}
	for _, path in ipairs(listfiles(folder)) do
		local name = path:match("([^/\\]+)%.json$")
		if name then
			table.insert(names, name)
		end
	end
	table.sort(names)
	return names
end

function Library:SetAutoload(name)
	if not hasFileApi() then
		return
	end
	ensureFolder(self.Folder)
	writefile(self.Folder .. "/autoload.txt", cleanName(name))
end

function Library:GetAutoload()
	local path = self.Folder .. "/autoload.txt"
	if hasFileApi() and isfile(path) then
		local name = readfile(path)
		return name ~= "" and name or nil
	end
	return nil
end

function Library:LoadAutoload()
	local name = self:GetAutoload()
	if name and self:LoadConfig(name) then
		self:Notify("Kompile", "Loaded config \"" .. name .. "\".")
	end
end

--// Built-in settings tab

local function sortedKeys(map)
	local keys = {}
	for key in pairs(map) do
		table.insert(keys, key)
	end
	table.sort(keys)
	return keys
end

function Library:BuildSettingsTab(window, name)
	local Tab = window:AddTab(name or "Settings")

	local Menu = Tab:AddLeftGroupbox("Menu")
	local MenuKey = Menu:AddKeybind("MenuKeybind", {
		Text = "Menu key",
		Default = self.ToggleKey and self.ToggleKey.Name or "RightShift",
		Mode = "Press",
		ShowInList = false,
	})
	MenuKey:OnChanged(function(key)
		Library:SetToggleKey(key)
	end)
	Menu:AddToggle("KeybindList", {
		Text = "Keybind list",
		Default = self.KeybindListEnabled,
		Tooltip = "Shows your bound keys and which features are on, even with the menu closed.",
		Callback = function(enabled)
			Library:SetKeybindList(enabled)
		end,
	})
	Menu:AddToggle("WindowGlow", {
		Text = "Window glow",
		Default = self.GlowEnabled,
		Callback = function(enabled)
			Library:SetGlow(enabled)
		end,
	})
	Menu:AddDropdown("AccentColor", {
		Text = "Accent",
		Values = sortedKeys(self.AccentPresets),
		Default = "Violet",
		Callback = function(value)
			Library:SetTheme({ Accent = Library.AccentPresets[value] })
		end,
	})
	Menu:AddDropdown("UIScale", {
		Text = "UI scale",
		Values = { "75%", "90%", "100%", "110%", "125%" },
		Default = "100%",
		Callback = function(value)
			Library:SetScale(tonumber((value:gsub("%%", ""))) / 100)
		end,
	})
	Menu:AddDivider()
	Menu:AddButton({
		Text = "Unload",
		Func = function()
			Library:Unload()
		end,
	})

	local Configs = Tab:AddRightGroupbox("Configs")
	if not hasFileApi() then
		Configs:AddLabel("Your executor can't save files, so configs aren't available.")
		return Tab
	end

	local ConfigName = Configs:AddInput("ConfigName", { Text = "Name", Placeholder = "my-config", Save = false })
	local ConfigList = Configs:AddDropdown("ConfigList", {
		Text = "Saved",
		Values = self:ListConfigs(),
		Placeholder = "None selected",
		Save = false,
	})
	local AutoloadLabel = Configs:AddLabel("Autoload: " .. (self:GetAutoload() or "none"))

	local function refresh()
		ConfigList:SetValues(Library:ListConfigs())
	end

	Configs:AddButton({
		Text = "Save",
		Tooltip = "Saves to the name you typed, or overwrites the selected config.",
		Func = function()
			local target = ConfigName.Value ~= "" and ConfigName.Value or ConfigList.Value
			local ok, result = Library:SaveConfig(target)
			if not ok then
				return Library:Notify("Kompile", result)
			end
			refresh()
			ConfigList:SetValue(result)
			Library:Notify("Kompile", "Saved \"" .. result .. "\".")
		end,
	})
	Configs:AddButton({
		Text = "Load",
		Func = function()
			if not ConfigList.Value then
				return Library:Notify("Kompile", "Pick a config first.")
			end
			local ok, err = Library:LoadConfig(ConfigList.Value)
			Library:Notify("Kompile", ok and ("Loaded \"" .. ConfigList.Value .. "\".") or err)
		end,
	})
	Configs:AddButton({
		Text = "Delete",
		Func = function()
			if not ConfigList.Value then
				return Library:Notify("Kompile", "Pick a config first.")
			end
			local target = ConfigList.Value
			local ok, err = Library:DeleteConfig(target)
			refresh()
			Library:Notify("Kompile", ok and ("Deleted \"" .. target .. "\".") or err)
		end,
	})
	Configs:AddButton({
		Text = "Set as autoload",
		Tooltip = "Loads this config automatically every time Kompile starts in this game.",
		Func = function()
			if not ConfigList.Value then
				return Library:Notify("Kompile", "Pick a config first.")
			end
			Library:SetAutoload(ConfigList.Value)
			AutoloadLabel:SetText("Autoload: " .. ConfigList.Value)
			Library:Notify("Kompile", "\"" .. ConfigList.Value .. "\" will load automatically.")
		end,
	})
	Configs:AddButton({ Text = "Refresh list", Func = refresh })

	return Tab
end

--// Lifecycle

function Library:OnUnload(fn)
	table.insert(UnloadCallbacks, fn)
end

function Library:Unload()
	if self.Unloaded then
		return
	end
	self.Unloaded = true
	for _, fn in ipairs(UnloadCallbacks) do
		local ok, err = pcall(fn)
		if not ok then
			warn("[Kompile UI] Unload callback error: " .. tostring(err))
		end
	end
	for _, connection in ipairs(Connections) do
		connection:Disconnect()
	end
	if self.ScreenGui then
		self.ScreenGui:Destroy()
	end
end

return Library
end)()

